    public static void main(String[] args) {
        String[] words = {"cascade", "cast", "castle"};
        String result = "";
        for (int i = 0; i < words[0].length(); i++) {
            char c = words[0].charAt(i);
            boolean same = true;
            for (int w = 1; w < words.length; w++) {
                if (i >= words[w].length() || words[w].charAt(i) != c) {
                    same = false;
                }
            }
            if (same == false) {
                break;
            }
            result = result + c;
        }
        System.out.println(result);
    }
}

